/**
 * competenceLevelColors — the colour each registered competence level is painted.
 *
 * Three themes are generated by sampling a stop list at N evenly spaced positions, N
 * being the band count of the level's scale; at N = 5 the sampling returns the stops
 * unchanged, so five-band scales keep their historical colors byte-for-byte. Within a
 * split band the levels are told apart by lightness: the highest sub-band keeps the
 * band's color and the lower ones are progressively darkened (`shadeSubBand`). The
 * fourth theme, `data`, uses the colors the state shipped in the payload and is only
 * offered when they are present and visible on the active colour scheme's surface.
 *
 * Interpolation is piecewise-linear in sRGB. It is only reached for band counts the
 * stops were not authored for, and swapping in a perceptual space later is a
 * one-function change (`mixHex`). Note that resampling a *diverging* ramp to N ≠ 5
 * moves the green off the exact centre band — that is inherent to resampling, not a bug.
 *
 * Reads the registry (`competenceLevelPalette.js`) and never writes it; the resolved
 * palette is memoised per scheme and theme and dropped whenever the registry's version
 * moves.
 * @module competenceLevelColors
 */

import {
    SURFACES,
    getRampStops,
    sampleRamp,
    shadeSubBand,
    contrastWithSurface,
} from './colorRamp.js';
import {
    getCompetencyBand,
    getPaletteVersion,
    getRegisteredLevels,
    isReportingEntry,
} from './competenceLevelPalette.js';

const DEFAULT_THEME_ID = 'default';

/** Theme that paints from the colors shipped in the data payload. */
export const DATA_THEME_ID = 'data';

/**
 * Contrast a shipped data color must clear against the chart surface of the active
 * colour scheme to be used under the `data` theme; below it the level falls back to its
 * generated ramp color.
 *
 * Deliberately far below the 3:1 floor the generated ramps are validated against.
 * The shipped palettes are Excel cell fills — light washes meant to sit behind black
 * text — and most of a state's ramp is typically under 3:1 (pale GER blues sit well
 * below 2:1). Applying the ramp floor here would discard the majority of every payload and leave a hybrid that is neither
 * the state's palette nor ours. Choosing the state's colors means accepting they read
 * light.
 *
 * What it cannot mean is a segment that is not there: NRW's ramp includes `#ffffff`,
 * which is the chart surface exactly (1.00:1). This threshold separates "invisible"
 * from "light" and nothing else.
 *
 * This is not hypothetical: NRW ships `#ffffff` for `KS 1` on both its Deutsch and its
 * Englisch ladders, and that band falls back to the generated ramp rather than painting
 * nothing.
 */
const MIN_SURFACE_CONTRAST = 1.1;

/** The colour scheme assumed when nothing is stamped on `<html>` (Node tests, first paint). */
const DEFAULT_SCHEME = 'light';

/** @type {Map<string, Map<string, string>>} `scheme:themeId` → (scoped level key → color) */
let _paletteCache = new Map();
/** @type {number} The registry version the cache was built against. */
let _cacheVersion = -1;

// ============================================================================
// PUBLIC API
// ============================================================================

/**
 * Whether the loaded data shipped its own colors that are visible on the active colour
 * scheme's surface. Gates the `data` theme — offering it against a payload of
 * `"description": null`, or one whose every colour is the surface itself, would just
 * repeat the default ramp.
 * @returns {boolean} True when at least one shipped level color will actually be painted.
 */
export function hasDataColors() {
    const surface = SURFACES[readActiveScheme()];
    for (const entry of getRegisteredLevels()) {
        if (entry.dataColor && isVisibleOn(entry.dataColor, surface)) return true;
    }
    return false;
}

/**
 * Resolved color for a competence level under a theme.
 * @param {string|number|null|undefined} level - Level to color.
 * @param {string} [themeId] - Defaults to the theme active on `<html>`
 * @param {string} [scaleId] - Which ladder `level` belongs to; see `getCompetencyBand`
 * @returns {string|null} Hex color, or null when `level` is not a registered level
 */
export function getBandColor(level, themeId = readActiveThemeId(), scaleId) {
    const entry = getCompetencyBand(level, scaleId);
    if (!entry) return null;
    return resolvePalette(themeId).get(entry.scopedKey) ?? null;
}

/**
 * Every registered level's color under a theme, keyed by the level's `nameShort`.
 * Feeds `getThemeColors().ks.byLevel`.
 * @param {string} [themeId] - Defaults to the theme active on `<html>`
 * @returns {{[level: string]: string}} Every registered level name mapped to its hex color under `themeId`.
 */
export function getBandColorsByLevel(themeId = readActiveThemeId()) {
    const palette = resolvePalette(themeId);
    /** @type {{[level: string]: string}} */
    const byLevel = {};
    for (const entry of getRegisteredLevels()) {
        // Reporting scales only. This map is keyed by bare name and is what the KS charts
        // and the sidebar thumbnail paint from, so an item scale in it would answer a
        // student level's colour lookup with the item ladder's ramp — exactly what
        // `bareNameIndex: false` prevents on `getCompetencyBand`. On a scale whose
        // reporting ladder is a prefix of its item ladder, every band would shift.
        if (!isReportingEntry(entry)) continue;
        const color = palette.get(entry.scopedKey);
        // Keyed by name, so two ladders sharing one name collapse to the last registered —
        // the same answer this returned before the registry became scale-aware. Callers
        // that must tell them apart use `getBandColor(level, themeId, scaleId)`.
        if (color) byLevel[entry.name] = color;
    }
    return byLevel;
}

// ============================================================================
// PRIVATE HELPERS
// ============================================================================

/**
 * The active KS theme, read from `<html>` — the same attribute `ksThemeService`
 * writes. Read directly rather than imported to keep this module dependency-free
 * (`ksThemeService` → `themeService` → here would be a cycle).
 * @returns {string} The theme id on `<html>`, or the default when there is no document.
 */
function readActiveThemeId() {
    if (typeof document === 'undefined') return DEFAULT_THEME_ID;
    return document.documentElement?.dataset?.ksTheme || DEFAULT_THEME_ID;
}

/**
 * The active colour scheme, read from `<html>` — the same attribute
 * `colorSchemeService` writes (always the *resolved* scheme, `light` or `dark`). Read
 * directly for the same reason as `readActiveThemeId`.
 * @returns {'light'|'dark'} The scheme on `<html>`, or light when there is no document.
 */
function readActiveScheme() {
    if (typeof document === 'undefined') return DEFAULT_SCHEME;
    const scheme = document.documentElement?.dataset?.colorScheme;
    return scheme === 'dark' ? 'dark' : DEFAULT_SCHEME;
}

/**
 * Whether a shipped colour clears `MIN_SURFACE_CONTRAST` on a surface — the "segment is
 * absent, not light" test. NRW ships `#ffffff` for `KS 1`: invisible on white, perfectly
 * visible on the dark surface, so the answer is per scheme.
 * @param {string} color - A hex literal.
 * @param {string} surface - The scheme's chart surface.
 * @returns {boolean} True when the colour will actually be seen.
 */
function isVisibleOn(color, surface) {
    return contrastWithSurface(color, surface) >= MIN_SURFACE_CONTRAST;
}

/**
 * Resolve (and memoise) the level → color map for a theme on the active colour scheme.
 * @param {string} themeId - Theme to resolve the ramp for.
 * @returns {Map<string, string>} Level key to hex color, memoised per scheme, theme and palette version.
 */
function resolvePalette(themeId) {
    const version = getPaletteVersion();
    if (version !== _cacheVersion) {
        _paletteCache = new Map();
        _cacheVersion = version;
    }

    const scheme = readActiveScheme();
    const cacheKey = `${scheme}:${themeId}`;
    const cached = _paletteCache.get(cacheKey);
    if (cached) return cached;

    const useDataColors = themeId === DATA_THEME_ID;
    const surface = SURFACES[scheme];
    const stops = getRampStops(themeId, scheme);

    /** @type {Map<number, string[]>} band count → sampled ramp, one scale usually */
    const rampsByCount = new Map();
    /** @type {Map<string, string>} */
    const palette = new Map();

    for (const entry of getRegisteredLevels()) {
        // A level whose shipped color is invisible on this surface falls through to
        // the generated ramp, exactly as one that shipped no color at all does.
        if (useDataColors && entry.dataColor && isVisibleOn(entry.dataColor, surface)) {
            palette.set(entry.scopedKey, entry.dataColor);
            continue;
        }
        let ramp = rampsByCount.get(entry.bandCount);
        if (!ramp) {
            ramp = sampleRamp(stops, entry.bandCount);
            rampsByCount.set(entry.bandCount, ramp);
        }
        palette.set(entry.scopedKey, shadeSubBand(ramp[entry.bandIndex], entry, scheme));
    }

    _paletteCache.set(cacheKey, palette);
    return palette;
}
